const $ = s => root.querySelector(s);
const DURATION = 25 * 60, KEY = 'pomodoro-pro-v1';
const dayKey = () => {const d=new Date();return d.getFullYear()+'-'+(d.getMonth()+1)+'-'+d.getDate();};
let storageOK = true, state;
const fresh = () => ({date:dayKey(),sessions:0,tasks:[],remaining:DURATION,end:null});
try {
 const saved=JSON.parse(localStorage.getItem(KEY)||'null');
 state=fresh();
 if(saved && typeof saved==='object'){
  state.date=typeof saved.date==='string'?saved.date:dayKey();
  state.sessions=Number.isSafeInteger(saved.sessions)&&saved.sessions>=0?saved.sessions:0;
  state.tasks=Array.isArray(saved.tasks)?saved.tasks.filter(t=>t&&typeof t.id==='string'&&typeof t.text==='string').map(t=>({id:t.id,text:t.text.slice(0,120),done:!!t.done})):[]; 
  state.remaining=Number.isFinite(saved.remaining)?Math.max(0,Math.min(DURATION,Math.ceil(saved.remaining))):DURATION;
  state.end=Number.isFinite(saved.end)&&saved.end>0?saved.end:null;
 }
} catch(e){state=fresh();storageOK=false;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch(e){storageOK=false;} $('[data-pp-storage]').textContent=storageOK?'进度自动保存在此浏览器 · 每日统计按本地日期更新':'浏览器存储不可用，当前进度仅保留至页面关闭';}
function syncDay(){if(state.date!==dayKey()){state.date=dayKey();state.sessions=0;state.tasks=[];save();renderTasks();} $('[data-pp-date]').textContent=new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'long'}).format(new Date());}
function renderStats(){const done=state.tasks.filter(t=>t.done).length,total=state.tasks.length,rate=total?Math.round(done/total*100):0;$('[data-pp-sessions]').textContent=state.sessions;$('[data-pp-minutes]').textContent=state.sessions*25;$('[data-pp-rate]').textContent=rate;$('[data-pp-rate-bar]').style.width=rate+'%';$('[data-pp-rate-note]').textContent=total?'已完成 '+done+' 项，共 '+total+' 项任务':'今天的进步，从这里开始';}
function renderTasks(){
 const list=$('[data-pp-list]');list.replaceChildren();
 state.tasks.forEach(task=>{
  const li=document.createElement('li');li.className='pp-task'+(task.done?' pp-task-done':'');
  const label=document.createElement('label'),check=document.createElement('input'),text=document.createElement('span'),del=document.createElement('button');
  check.type='checkbox';check.checked=task.done;text.className='pp-task-name';text.textContent=task.text;
  check.addEventListener('change',()=>{task.done=check.checked;save();renderTasks();});
  del.type='button';del.className='pp-task-delete';del.textContent='×';del.setAttribute('aria-label','删除任务：'+task.text);
  del.addEventListener('click',()=>{state.tasks=state.tasks.filter(t=>t.id!==task.id);save();renderTasks();});
  label.append(check,text);li.append(label,del);list.append(li);
 });
 const done=state.tasks.filter(t=>t.done).length,pending=state.tasks.length-done;
 $('[data-pp-empty]').hidden=state.tasks.length>0;$('[data-pp-task-count]').textContent=done+' / '+state.tasks.length+' 完成';
 $('[data-pp-pending]').textContent=state.tasks.length?(pending?'还有 '+pending+' 件事，慢慢来':'今日任务全部完成，做得很好'):'等待你的第一个目标';
 $('[data-pp-clear]').hidden=done===0;renderStats();
}
function renderTimer(){
 const seconds=state.remaining;
 $('[data-pp-time]').textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');
 $('[data-pp-toggle-text]').textContent=state.end?'暂停专注':seconds===0?'再来一轮':seconds<DURATION?'继续专注':'开始专注';
 $('[data-pp-toggle-icon]').textContent=state.end?'Ⅱ':'▶';
 $('[data-pp-phase]').textContent=state.end?'心流进行中':seconds===0?'本轮专注已完成':seconds<DURATION?'稍作停顿，随时继续':'准备好进入心流';
 $('.pp-ring-progress').style.strokeDashoffset=String((1-seconds/DURATION)*100);
}
function finish(){
 const finishedAt=state.end;state.end=null;state.remaining=0;
 const finishDate=new Date(finishedAt-1);
 const finishDay=finishDate.getFullYear()+'-'+(finishDate.getMonth()+1)+'-'+finishDate.getDate();
 if(finishDay===state.date) state.sessions++;
 save();renderStats();renderTimer();
 $('[data-pp-status]').textContent='一轮专注完成！起身活动一下，休息 5 分钟。';
}
function tick(){syncDay();if(state.end){const left=Math.max(0,Math.ceil((state.end-Date.now())/1000));if(left===0)finish();else if(left!==state.remaining){state.remaining=left;renderTimer();}}}
$('[data-pp-toggle]').addEventListener('click',()=>{
 syncDay();
 if(state.end){
  const left=Math.max(0,Math.ceil((state.end-Date.now())/1000));
  if(left===0){finish();return;}
  state.remaining=left;state.end=null;
  $('[data-pp-status]').textContent='已暂停。准备好后，继续这一轮专注。';
 }else{
  if(state.remaining===0)state.remaining=DURATION;
  state.end=Date.now()+state.remaining*1000;
  $('[data-pp-status]').textContent='正在专注。此刻，只需要做好眼前这一件事。';
 }
 save();renderTimer();
});
$('[data-pp-reset]').addEventListener('click',()=>{
 tick();state.end=null;state.remaining=DURATION;save();renderTimer();
 $('[data-pp-status]').textContent='已重置为 25 分钟。新的专注，从现在开始。';
});
$('[data-pp-form]').addEventListener('submit',e=>{
 e.preventDefault();syncDay();const input=$('[data-pp-input]'),text=input.value.trim();if(!text){input.value='';input.focus();return;}
 state.tasks.push({id:globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2),text:text.slice(0,120),done:false});input.value='';save();renderTasks();input.focus();
});
$('[data-pp-clear]').addEventListener('click',()=>{syncDay();state.tasks=state.tasks.filter(t=>!t.done);save();renderTasks();});
syncDay();renderTasks();tick();renderTimer();save();
if(state.end)$('[data-pp-status]').textContent='已恢复进行中的专注，继续做好眼前这一件事。';
else if(state.remaining<DURATION&&state.remaining>0)$('[data-pp-status]').textContent='已恢复上次暂停的进度，准备好就继续。';
const interval=setInterval(tick,250);
const onVisible=()=>{if(!document.hidden)tick();};
document.addEventListener('visibilitychange',onVisible);
return ()=>{clearInterval(interval);document.removeEventListener('visibilitychange',onVisible);};
